    private final Field f4_WS_RECV = Field.group(s_WS_RECV, 0, 79);
    private final Field f6_WS_RECV_DATA = Field.alphanumeric(s_WS_RECV, 5, 74, false);
    private final Field f7_WS_RECV_LEN = Field.binary(s_WS_RECV_LEN, 0, 4, 0, true, false);
    private final Field f8_WRITE_MSG = Field.group(s_WRITE_MSG, 0, 95);
